  const captured=document.querySelector('#txtsecuritycode')?.closest('.captured-form');if(!captured)throw Error('Captured guest lookup unavailable');const form=activate(captured,'starnik-guest-lookup'),error=errorFor(form),button=form.querySelector('button');
  for(const[id,name,label]of [['txtsecuritycode','securityCode','Account Security Code'],['txtservicezipcode','serviceZip','Service Zip Code']]){const field=form.querySelector('#'+id);field.disabled=false;field.name=name;field.required=true;field.setAttribute('aria-label',label);}
