   // Keep the chosen method and amount when the customer returns from review (Back link or browser Back).
   const draftKey='starnik-payment-draft',readDraft=()=>{try{return JSON.parse(sessionStorage.getItem(draftKey)||'null');}catch{return null;}},saveDraft=d=>{try{sessionStorage.setItem(draftKey,JSON.stringify(d));}catch{}};
   const form=root.querySelector('form');if(form){const draft=readDraft();if(draft&&draft.account===v.account.customerNumber&&draft.balanceCents===v.balanceCents&&v.methods.some(m=>m.id===draft.methodId)){form.elements.methodId.value=draft.methodId;if(typeof draft.amount==='string'&&draft.amount)form.elements.amount.value=draft.amount;}const error=errorFor(form);form.onsubmit=async e=>{e.preventDefault();const value=form.elements.amount.value;saveDraft({account:v.account.customerNumber,balanceCents:v.balanceCents,methodId:form.elements.methodId.value,amount:value});if(!/^\d+(?:\.\d{1,2})?$/.test(value)){error.textContent='Enter a payment amount with no more than two decimals';return;}const[whole,fraction='']=value.split('.');const button=form.querySelector('button');button.disabled=true;try{await api('payment/prepare',{methodId:form.elements.methodId.value,amountCents:Number(whole)*100+Number(fraction.padEnd(2,'0'))});location.assign('/starnik/payment/review');}catch(e){error.textContent=e.message;button.disabled=false;}};}return;
