   root.innerHTML+='<form id="starnik-payment-confirm"><label><input name="authorize" type="checkbox" required> I authorize this payment and the displayed fee.</label><button>Confirm and Pay</button><a href="/starnik/guest/account">Back</a></form>';const form=root.querySelector('form'),error=errorFor(form);form.onsubmit=async e=>{e.preventDefault();if(!await ask('Do you want to submit this payment?'))return;const button=form.querySelector('button');button.disabled=true;try{const result=await api('guest/pay',{authorize:form.elements.authorize.checked});if(result.declined){error.textContent=result.message;button.disabled=false;}else location.assign('/starnik/guest/receipt');}catch(e){error.textContent=e.message;button.disabled=false;}};return;
