  document.body.innerHTML='<main class="starnik-local"><h1>Account Sign Up</h1><p>Local construction continuation. Verification delivery and account setup are simulated from the public client sequence.</p><section id="starnik-signup-content"></section></main>';const root=document.querySelector('section');
